Body:
## Regression tests (standalone, run with vitest + solid-js)

These tests exercise the exact `setLocationSlice` helper from this PR against Solid's real `createStore`/`setStore`. They cover the race conditions the fix addresses.

```ts
import { describe, it, expect } from "vitest"
import { createStore } from "solid-js/store"

type LocationData = {
  agent?: unknown[]
  command?: unknown[]
  integration?: unknown[]
  model?: unknown[]
  provider?: unknown[]
  reference?: unknown[]
  skill?: unknown[]
}

type Data = {
  location: Record<string, LocationData>
}

function locationKey(location: { directory: string; workspaceID?: string }) {
  return JSON.stringify([location.directory, location.workspaceID])
}

// Same helper as in the data.tsx patch
function setLocationSlice(
  setStore: (path: string, key: string, updater: (prev: LocationData | undefined) => LocationData) => void,
  key: string,
  slice: keyof LocationData,
  data: unknown,
) {
  setStore("location", key, (prev) => ({ ...(prev ?? {}), [slice]: data }))
}

describe("setLocationSlice (location-refresh race fix)", () => {
  it("creates a missing key without crashing (a[t] race)", () => {
    const [store, setStore] = createStore<Data>({ location: {} })
    const key = locationKey({ directory: "/home/juku" })

    // Sub-refresh resolves before location.refresh() finishes:
    // store.location[key] is undefined, but the write must not throw.
    expect(() => setLocationSlice(setStore, key, "agent", [{ id: "a1" }])).not.toThrow()
    expect(store.location[key]?.agent).toEqual([{ id: "a1" }])
  })

  it("does not clobber other slices under the same key", () => {
    const [store, setStore] = createStore<Data>({ location: {} })
    const key = locationKey({ directory: "/home/juku" })

    setLocationSlice(setStore, key, "agent", [{ id: "a1" }])
    setLocationSlice(setStore, key, "model", [{ id: "m1" }])

    expect(store.location[key]?.agent).toEqual([{ id: "a1" }])
    expect(store.location[key]?.model).toEqual([{ id: "m1" }])
  })

  it("TOCTOU: workspace switch discards stale response", () => {
    const [store, setStore] = createStore<Data>({ location: {} })
    const keyA = locationKey({ directory: "/home/juku", workspaceID: "ws-a" })
    const keyB = locationKey({ directory: "/home/juku", workspaceID: "ws-b" })

    // refresh() started for workspace A, but the response came back for B
    const expectedKey = keyA
    const responseKey = keyB
    if (expectedKey !== responseKey) return // TOCTOU guard: do not write

    setLocationSlice(setStore, responseKey, "agent", [{ id: "a1" }])
    expect(store.location[keyA]).toBeUndefined()
  })

  it("null-guard: missing response location does not write", () => {
    const [store, setStore] = createStore<Data>({ location: {} })
    const key = locationKey({ directory: "/home/juku" })

    // Malformed response: result.data.location is undefined
    const location = undefined
    if (!location) return // null-guard

    setLocationSlice(setStore, key, "agent", [{ id: "a1" }])
    expect(store.location[key]).toBeUndefined()
  })

  it("allSettled error tolerance: one slice fails, others do not", async () => {
    const [store, setStore] = createStore<Data>({ location: {} })
    const key = locationKey({ directory: "/home/juku" })

    const failing = Promise.reject(new Error("network"))
    const ok = Promise.resolve({ data: { location: { directory: "/home/juku" }, data: [{ id: "m1" }] } })

    const settled = await Promise.allSettled([failing, ok])
    expect(settled[0].status).toBe("rejected")
    expect(settled[1].status).toBe("fulfilled")

    const result = await ok
    setLocationSlice(setStore, key, "model", result.data.data)
    expect(store.location[key]?.model).toEqual([{ id: "m1" }])
  })
})
```

Run: `npm i -D vitest solid-js && npx vitest run` (5/5 pass).
